struct Ctx {
    root: PathBuf,
    loader: Loader,
}

struct Entry {
    /// `str(path.relative_to(REPO_ROOT))`: joined with the OS separator.
    path: String,
    parts: Vec<String>,
    loc: usize,
    summary: String,
}

// ------------------------------------------------------------------
// Source scanners
// ------------------------------------------------------------------

fn read_utf8(path: &Path) -> String {
    pyio::read_text_utf8(path).unwrap_or_else(|exc| uncaught(&exc))
}

fn count_loc(text: &str) -> usize {
    py_splitlines(text)
        .into_iter()
        .filter(|line| {
            let stripped = py_strip(line);
            !stripped.is_empty() && !stripped.starts_with('#')
        })
        .count()
}

fn expandtabs(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut col = 0usize;
    for ch in text.chars() {
        match ch {
            '\t' => {
                let n = 8 - col % 8;
                out.extend(std::iter::repeat(' ').take(n));
                col += n;
            }
            '\n' | '\r' => {
                out.push(ch);
                col = 0;
            }
            _ => {
                out.push(ch);
                col += 1;
            }
        }
    }
    out
}

/// `module_docstring`: first line of the cleaned docstring, trailing dots
/// removed. `inspect.cleandoc` only removes leading whitespace (and blank
/// edge lines), so after `.strip()` the first line is that of the
/// tab-expanded raw docstring.
fn module_docstring(text: &str) -> String {
    let Some(doc) = pyast::module_docstring(text) else { return String::new() };
    let expanded = expandtabs(&doc);
    let stripped = py_strip(&expanded);
    stripped.split('\n').next().unwrap_or("").trim_end_matches('.').to_string()
}

fn rglob_py(dir: &Path, parts: &mut Vec<String>, out: &mut Vec<Vec<String>>) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        let path = entry.path();
        parts.push(name.clone());
        let matches = if cfg!(windows) { name.to_lowercase().ends_with(".py") } else { name.ends_with(".py") };
        if matches {
            out.push(parts.clone());
        }
        if path.is_dir() {
            rglob_py(&path, parts, out);
        }
        parts.pop();
    }
}

/// `sorted(PKG_DIR.rglob("*.py"))` minus `__pycache__`, with LOC and summary.
fn scan_package(root: &Path) -> Vec<Entry> {
    let mut found = Vec::new();
    rglob_py(&root.join("coordinationhub"), &mut vec!["coordinationhub".to_string()], &mut found);
    // PurePath ordering compares the (case-folded on Windows) parts.
    let key = |parts: &Vec<String>| -> Vec<String> {
        if cfg!(windows) {
            parts.iter().map(|p| p.to_lowercase()).collect()
        } else {
            parts.clone()
        }
    };
    found.sort_by_key(key);
    let mut entries = Vec::new();
    for parts in found {
        if parts.iter().any(|p| p == "__pycache__") {
            continue;
        }
        let mut full = root.to_path_buf();
        for part in &parts {
            full.push(part);
        }
        let text = read_utf8(&full);
        let loc = count_loc(&text);
        let summary = module_docstring(&text);
        entries.push(Entry { path: pyio::join_os(&parts), parts, loc, summary });
    }
    entries
}

fn get_version(root: &Path) -> String {
    let init_path = root.join("coordinationhub").join("__init__.py");
    let text = pyio::read_text_locale(&init_path).unwrap_or_else(|exc| uncaught(&exc));
    for line in py_splitlines(&text) {
        if line.starts_with("__version__") {
            let Some((_, value)) = line.split_once('=') else {
                uncaught("IndexError: list index out of range");
            };
            return py_strip(value).trim_matches('"').trim_matches('\'').to_string();
        }
    }
    uncaught(&format!("RuntimeError: __version__ not found in {}", pyio::path_str(&init_path)))
}

/// The `(\d+)` run starting at `start`, if `\s+tests?\s+collected` follows.
fn digits_then(chars: &[char], start: usize, tail_collected: bool) -> Option<String> {
    let mut i = start;
    while i < chars.len() && pyio::py_digit(chars[i]) {
        i += 1;
    }
    if i == start {
        return None;
    }
    let number: String = chars[start..i].iter().collect();
    let ws_start = i;
    while i < chars.len() && py_isspace(chars[i]) {
        i += 1;
    }
    if i == ws_start {
        return None;
    }
    let rest: String = chars[i..].iter().collect();
    let after = rest.strip_prefix("test")?;
    let after = after.strip_prefix('s').unwrap_or(after);
    if tail_collected {
        let trimmed = after.trim_start_matches(py_isspace);
        if trimmed.len() == after.len() {
            return None;
        }
        trimmed.starts_with("collected").then_some(number)
    } else {
        after.is_empty().then_some(number)
    }
}

fn int_text(digits: &str) -> String {
    let trimmed = digits.trim_start_matches('0');
    if trimmed.is_empty() {
        "0".into()
    } else {
        trimmed.into()
    }
}

/// `get_test_count`: `python -m pytest --collect-only -q tests/`.
fn get_test_count(root: &Path) -> String {
    let argv: Vec<String> =
        ["python", "-m", "pytest", "--collect-only", "-q", "tests/"].iter().map(|s| s.to_string()).collect();
    let result = pyio::run_text(&argv, root);
    let stdout = result.stdout.unwrap_or_else(|| pyio::none_attr("strip"));
    let stdout = py_strip(&stdout).to_string();
    for line in py_splitlines(&stdout).into_iter().rev() {
        let chars: Vec<char> = line.chars().collect();
        for start in 0..chars.len() {
            if pyio::py_digit(chars[start]) && (start == 0 || !pyio::py_digit(chars[start - 1])) {
                if let Some(number) = digits_then(&chars, start, true) {
                    return int_text(&number);
                }
            }
        }
        let stripped: Vec<char> = py_strip(line).chars().collect();
        if let Some(number) = digits_then(&stripped, 0, false) {
            return int_text(&number);
        }
    }
    "0".into()
}

fn get_schema_version(root: &Path) -> String {
    let path = root.join("coordinationhub").join("db_migrations.py");
    let text = read_utf8(&path);
    for line in py_splitlines(&text) {
        let Some(rest) = line.strip_prefix("_CURRENT_SCHEMA_VERSION") else { continue };
        let rest = rest.trim_start_matches(py_isspace);
        let Some(rest) = rest.strip_prefix('=') else { continue };
        let rest = rest.trim_start_matches(py_isspace);
        let digits: String = rest.chars().take_while(|c| pyio::py_digit(*c)).collect();
        if digits.is_empty() {
            continue;
        }
        if rest[digits.len()..].chars().all(py_isspace) {
            return digits;
        }
    }
    uncaught(&format!("RuntimeError: _CURRENT_SCHEMA_VERSION not found in {}", pyio::path_str(&path)))
}

fn import_value(ctx: &Ctx, module: &str, name: &str) -> Val {
    match ctx.loader.import_from(module, name) {
        Ok(value) => value,
        Err(pyast::EvalError::Python(exc)) => uncaught(&exc),
        Err(pyast::EvalError::Unsupported(what)) => uncaught(&format!(
            "NotImplementedError: the Rust port evaluates module constants statically and cannot evaluate {what}"
        )),
    }
}

/// A value the script goes on to use must be statically known; one only
/// CPython's import could compute (a call, an env lookup) stops the port.
fn known(value: &Val) -> &Val {
    value.known().unwrap_or_else(|what| {
        uncaught(&format!(
            "NotImplementedError: the Rust port evaluates module constants statically and cannot evaluate {what}"
        ))
    })
}

fn py_len(value: &Val) -> usize {
    match known(value) {
        Val::Dict(items) => items.len(),
        Val::List(items) | Val::Tuple(items) => items.len(),
        Val::Str(text) => text.chars().count(),
        other => uncaught(&format!("TypeError: object of type '{}' has no len()", other.type_name())),
    }
}

fn no_attr(value: &Val, attr: &str) -> ! {
    let value = known(value);
    uncaught(&format!("AttributeError: '{}' object has no attribute '{attr}'", value.type_name()))
}

fn get_mcp_tools(ctx: &Ctx) -> Vec<(String, String)> {
    let schemas = import_value(ctx, "coordinationhub.schemas", "TOOL_SCHEMAS");
    let Val::Dict(items) = &schemas else { no_attr(&schemas, "items") };
    let mut out = Vec::new();
    for (name, spec) in items {
        let Val::Dict(spec_items) = spec else { no_attr(spec, "get") };
        let desc = match dict_get(spec_items, "description") {
            None => String::new(),
            Some(Val::Str(text)) => text.clone(),
            Some(other) => no_attr(other, "strip"),
        };
        let desc = py_strip(&desc);
        let first = desc.split(". ").next().unwrap_or("").trim_end_matches('.');
        let first = if first.chars().count() > 120 {
            format!("{}...", first.chars().take(117).collect::<String>())
        } else {
            first.to_string()
        };
        out.push((name.py_str(), first));
    }
    out
}

// ------------------------------------------------------------------
// Renderers
// ------------------------------------------------------------------

fn escape_pipe(text: &str) -> String {
    text.replace('|', "\\|")
}

fn render_file_inventory(entries: &[Entry]) -> String {
    let mut lines = vec!["| Path | LOC | Purpose |".to_string(), "|------|-----|---------|".to_string()];
    for e in entries {
        let summary = escape_pipe(if e.summary.is_empty() { "—" } else { &e.summary });
        lines.push(format!("| `{}` | {} | {} |", e.path, e.loc, summary));
    }
    lines.join("\n")
}

fn render_directory_tree(entries: &[Entry]) -> String {
    let mut lines = vec!["```".to_string(), "coordinationhub/".to_string()];
    let mut by_dir: Vec<(String, Vec<&Entry>)> = Vec::new();
    for e in entries {
        let key = if e.parts.len() == 2 { String::new() } else { e.parts[1..e.parts.len() - 1].join("/") };
        match by_dir.iter_mut().find(|(k, _)| *k == key) {
            Some((_, list)) => list.push(e),
            None => by_dir.push((key, vec![e])),
        }
    }
    let name = |e: &Entry| e.parts.last().cloned().unwrap_or_default();
    if let Some((_, top)) = by_dir.iter().find(|(k, _)| k.is_empty()) {
        let mut top = top.clone();
        top.sort_by_key(|e| name(e));
        for e in top {
            let n = name(e);
            let pad = 22usize.saturating_sub(n.chars().count()).max(1);
            lines.push(format!("  {n}{}— {} (~{} LOC)", " ".repeat(pad), e.summary, e.loc));
        }
    }
    let mut keys: Vec<&String> = by_dir.iter().map(|(k, _)| k).filter(|k| !k.is_empty()).collect();
    keys.sort();
    for key in keys {
        lines.push(format!("  {key}/"));
        let mut list = by_dir.iter().find(|(k, _)| k == key).expect("dir").1.clone();
        list.sort_by_key(|e| name(e));
        for e in list {
            let n = name(e);
            let pad = 20usize.saturating_sub(n.chars().count()).max(1);
            lines.push(format!("    {n}{}— {} (~{} LOC)", " ".repeat(pad), e.summary, e.loc));
        }
    }
    lines.push("```".to_string());
    lines.join("\n")
}

fn render_mcp_tools(tools: &[(String, String)]) -> String {
    let mut lines = vec!["| Tool | Description |".to_string(), "|------|-------------|".to_string()];
    for (name, desc) in tools {
        lines.push(format!("| `{name}` | {} |", escape_pipe(desc)));
    }
    lines.join("\n")
}

fn tier_for(path: &str) -> (&'static str, Option<usize>) {
    for (suffix, tier, cap) in LOC_TIERS {
        if path.ends_with(suffix) {
            return (tier, *cap);
        }
    }
    ("primitive", Some(550))
}

fn check_tier_coverage(entries: &[Entry]) -> Vec<(String, &'static str)> {
    let mut nudges = Vec::new();
    for entry in entries {
        let path = &entry.path;
        if LOC_TIERS.iter().any(|(suffix, _, _)| path.ends_with(suffix)) {
            continue;
        }
        for (pattern, is_prefix, tier) in TIER_INFERENCE {
            let hit = if *is_prefix {
                path.starts_with(pattern) && path[pattern.len()..].ends_with(".py")
            } else {
                path == pattern
            };
            if hit {
                nudges.push((path.clone(), *tier));
                break;
            }
        }
    }
    nudges
}

fn render_largest_files(entries: &[Entry]) -> String {
    let mut rows = vec!["| Path | Code-LOC | Tier | Status |".to_string(), "|------|----------|------|--------|".to_string()];
    let mut biggest: Vec<&Entry> = entries.iter().collect();
    biggest.sort_by(|a, b| b.loc.cmp(&a.loc));
    for e in biggest.into_iter().take(8) {
        let (tier, cap) = tier_for(&e.path);
        let status = match cap {
            None => "exempt".to_string(),
            Some(cap) if e.loc <= cap => format!("OK (≤ {cap})"),
            Some(cap) => format!("OVER (cap {cap}) — split planned"),
        };
        rows.push(format!("| `{}` | {} | {tier} | {status} |", e.path, e.loc));
    }
    rows.join("\n")
}

// ------------------------------------------------------------------
// Dispatch coverage
// ------------------------------------------------------------------

fn parse_core(root: &Path) -> Vec<Stmt> {
    let text = read_utf8(&root.join("coordinationhub").join("core.py"));
    pyast::ast_parse(&text).unwrap_or_else(|e| uncaught(&e.exception_line()))
}

fn engine_class(stmts: &[Stmt]) -> &Stmt {
    find_class_bfs(stmts, "CoordinationEngine").unwrap_or_else(|| uncaught("StopIteration"))
}

/// The statements of a def/class body, as `ast` lists them (decorator
/// lines belong to the following def; `;` separates statements).
fn body_parts(def: &Stmt) -> Vec<BodyItem<'_>> {
    let mut out: Vec<BodyItem> = inline_body(&def.toks).into_iter().map(BodyItem::Simple).collect();
    for stmt in &def.body {
        match classify_line(stmt) {
            Line::Decorator => {}
            Line::Simple => out.extend(simple_parts(stmt).into_iter().map(BodyItem::Simple)),
            _ => out.push(BodyItem::Compound),
        }
    }
    out
}

enum BodyItem<'a> {
    Simple(&'a [pytok::Tok]),
    /// A compound statement, def or class: never a facade `return`.
    Compound,
}

/// `_build_engine_subsystem_map`: `{attr: (class, module)}` from the
/// `self._x = Class(...)` assignments in `CoordinationEngine.__init__`.
fn build_engine_subsystem_map(root: &Path) -> Vec<(String, (String, String))> {
    let stmts = parse_core(root);
    let mut class_to_module: Vec<(String, String)> = Vec::new();
    for stmt in &stmts {
        if !matches!(classify_line(stmt), Line::Simple) {
            continue;
        }
        for part in simple_parts(stmt) {
            if let Simple::ImportFrom(toks) = classify_simple(part) {
                if let Some((level, Some(module), names)) = parse_import_from(toks) {
                    if level >= 1 {
                        for (orig, _) in names {
                            match class_to_module.iter_mut().find(|(k, _)| *k == orig) {
                                Some(slot) => slot.1 = module.clone(),
                                None => class_to_module.push((orig, module.clone())),
                            }
                        }
                    }
                }
            }
        }
    }
    let cls = engine_class(&stmts);
    let mut out: Vec<(String, (String, String))> = Vec::new();
    let init = cls.body.iter().find(|s| matches!(classify_line(s), Line::Def { name: "__init__", is_async: false }));
    let Some(init) = init else { return out };
    let mut assigns: Vec<(usize, usize, &[pytok::Tok], &[pytok::Tok])> = Vec::new();
    let mut seq = 0usize;
    for part in inline_body(&init.toks) {
        collect_assign(part, 1, &mut seq, &mut assigns);
    }
    walk_assigns(&init.body, 1, &mut seq, &mut assigns);
    assigns.sort_by_key(|(depth, order, _, _)| (*depth, *order));
    for (_, _, target, value) in assigns {
        let Some(Expr::Attr(base, attr)) = parse_expr(target) else { continue };
        if !matches!(*base, Expr::Name(ref n) if n == "self") || !attr.starts_with('_') {
            continue;
        }
        let Some(Expr::Call(func)) = parse_expr(value) else { continue };
        let Expr::Name(cls_name) = *func else { continue };
        let Some((_, module)) = class_to_module.iter().find(|(k, _)| *k == cls_name) else { continue };
        let entry = (cls_name.clone(), module.clone());
        match out.iter_mut().find(|(k, _)| *k == attr) {
            Some(slot) => slot.1 = entry,
            None => out.push((attr, entry)),
        }
    }
    out
}

type Assign<'a> = (usize, usize, &'a [pytok::Tok], &'a [pytok::Tok]);

fn collect_assign<'a>(part: &'a [pytok::Tok], depth: usize, seq: &mut usize, out: &mut Vec<Assign<'a>>) {
    if let Simple::Assign { targets, value } = classify_simple(part) {
        if targets.len() == 1 {
            out.push((depth, *seq, targets[0], value));
        }
    }
    *seq += 1;
}

/// Walk a block in `ast.walk` (breadth-first) depth terms: a compound
/// statement's body is one level down, an `except` body two (the handler
/// node sits between), the n-th `elif` body n+1 (nested `If` nodes).
fn walk_assigns<'a>(stmts: &'a [Stmt], depth: usize, seq: &mut usize, out: &mut Vec<Assign<'a>>) {
    let mut elifs = 0usize;
    let mut last_if_chain = false;
    for stmt in stmts {
        let line = classify_line(stmt);
        let body_depth = match &line {
            Line::Simple => {
                for part in simple_parts(stmt) {
                    collect_assign(part, depth, seq, out);
                }
                last_if_chain = false;
                continue;
            }
            Line::Decorator => continue,
            Line::Compound { keyword } => match *keyword {
                "if" => {
                    elifs = 0;
                    last_if_chain = true;
                    depth + 1
                }
                "elif" => {
                    elifs += 1;
                    depth + 1 + elifs
                }
                "else" if last_if_chain => {
                    last_if_chain = false;
                    depth + 1 + elifs
                }
                "except" => depth + 2,
                _ => {
                    last_if_chain = false;
                    depth + 1
                }
            },
            Line::Def { .. } | Line::Class { .. } => {
                last_if_chain = false;
                depth + 1
            }
        };
        for part in inline_body(&stmt.toks) {
            collect_assign(part, body_depth, seq, out);
        }
        walk_assigns(&stmt.body, body_depth, seq, out);
    }
}

/// `_engine_facade_target`: `(subsystem_attr, method)` when the engine
/// method's body (docstrings and other constant expressions aside) is a
/// single `return self._<sub>.<method>(...)`.
/// Like the script, it re-reads and re-parses `core.py` on every call.
fn engine_facade_target(root: &Path, method_name: Option<&str>) -> Option<(String, String)> {
    let stmts = parse_core(root);
    let cls = engine_class(&stmts);
    let method_name = method_name?;
    let def = cls.body.iter().find(|s| matches!(classify_line(s), Line::Def { name, .. } if name == method_name))?;
    let body: Vec<BodyItem> = body_parts(def)
        .into_iter()
        .filter(|item| !matches!(item, BodyItem::Simple(toks) if matches!(classify_simple(toks), Simple::Expr(e) if is_constant(e))))
        .collect();
    if body.len() != 1 {
        return None;
    }
    let BodyItem::Simple(toks) = body[0] else { return None };
    let Simple::Return(value) = classify_simple(toks) else { return None };
    let Some(Expr::Call(func)) = parse_expr(value) else { return None };
    let Expr::Attr(receiver, method) = *func else { return None };
    let Expr::Attr(base, attr) = *receiver else { return None };
    if !matches!(*base, Expr::Name(ref n) if n == "self") || !attr.starts_with('_') {
        return None;
    }
    Some((attr, method))
}

fn bytes_repr(bytes: &[u8]) -> String {
    let quote = if bytes.contains(&b'\'') && !bytes.contains(&b'"') { '"' } else { '\'' };
    let mut out = format!("b{quote}");
    for &b in bytes {
        match b {
            b'\\' => out.push_str("\\\\"),
            b'\t' => out.push_str("\\t"),
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            _ if b as char == quote => {
                out.push('\\');
                out.push(quote);
            }
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{b:02x}")),
        }
    }
    out.push(quote);
    out
}

/// `repr()` of the exception reading + decoding `coverage.json` raised.
fn load_coverage(path: &Path) -> Result<J, String> {
    let bytes = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(err) => {
            return Err(match err.kind() {
                std::io::ErrorKind::NotFound => "FileNotFoundError(2, 'No such file or directory')".into(),
                std::io::ErrorKind::PermissionDenied => "PermissionError(13, 'Permission denied')".into(),
                _ => format!("OSError({})", py_repr(&err.to_string())),
            })
        }
    };
    let text = match std::str::from_utf8(&bytes) {
        Ok(text) => pyio::universal_newlines(text),
        Err(err) => {
            let start = err.valid_up_to();
            let (end, reason) = match err.error_len() {
                None => (bytes.len(), "unexpected end of data"),
                Some(len) => (
                    start + len,
                    if matches!(bytes[start], 0xC2..=0xF4) { "invalid continuation byte" } else { "invalid start byte" },
                ),
            };
            return Err(format!("UnicodeDecodeError('utf-8', {}, {start}, {end}, '{reason}')", bytes_repr(&bytes)));
        }
    };
    pyjson::loads(&text).map_err(|msg| format!("JSONDecodeError({})", py_repr(&msg)))
}

fn json_get<'a>(value: &'a J, key: &str) -> Option<&'a J> {
    match value {
        J::Obj(_) => value.get(key),
        other => uncaught(&format!("AttributeError: '{}' object has no attribute 'get'", other.type_name())),
    }
}

fn coverage_for_function(data: &J, file_path: &str, qualified: &str) -> Option<(String, String)> {
    let empty = J::Obj(Vec::new());
    let files = json_get(data, "files").unwrap_or(&empty);
    let file_entry = json_get(files, file_path).filter(|v| v.truthy())?;
    let functions = json_get(file_entry, "functions").unwrap_or(&empty);
    let fn_entry = json_get(functions, qualified).filter(|v| v.truthy())?;
    let summary = json_get(fn_entry, "summary").unwrap_or(&empty);
    let line_pct = json_get(summary, "percent_covered_display").map(J::py_str).unwrap_or_else(|| "?".into());
    let branch_pct = json_get(summary, "percent_branches_covered_display").map(J::py_str).unwrap_or_else(|| "?".into());
    Some((format!("{line_pct}%"), format!("{branch_pct}%")))
}

fn render_dispatch_coverage(ctx: &Ctx) -> String {
    let coverage_json = ctx.root.join("coverage.json");
    if !coverage_json.exists() {
        return "_No `coverage.json` found. Run `pytest --cov=coordinationhub --cov-report=json --cov-branch` then \
                `python scripts/gen_docs.py` to regenerate this table._"
            .to_string();
    }
    let data = match load_coverage(&coverage_json) {
        Ok(data) => data,
        Err(repr) => return format!("_coverage.json present but unreadable: {repr}_"),
    };
    let sub_map = build_engine_subsystem_map(&ctx.root);
    let _schemas = import_value(ctx, "coordinationhub.schemas", "TOOL_SCHEMAS");
    let dispatch = import_value(ctx, "coordinationhub.dispatch", "TOOL_DISPATCH");
    let Val::Dict(dispatch_items) = &dispatch else { no_attr(&dispatch, "__getitem__") };
    let mut tools: Vec<(String, &Val)> = dispatch_items.iter().map(|(k, v)| (k.py_str(), v)).collect();
    tools.sort_by(|a, b| a.0.cmp(&b.0));
    let mut rows: Vec<(String, String, String, String, f64)> = Vec::new();
    for (tool, value) in tools {
        let unpack = |count: usize| -> ! {
            if count > 2 {
                uncaught("ValueError: too many values to unpack (expected 2)")
            }
            uncaught(&format!("ValueError: not enough values to unpack (expected 2, got {count})"))
        };
        let engine_method = match known(value) {
            Val::Tuple(items) | Val::List(items) if items.len() == 2 => items[0].clone(),
            Val::Tuple(items) | Val::List(items) => unpack(items.len()),
            Val::Str(text) if text.chars().count() == 2 => Val::Str(text.chars().take(1).collect()),
            Val::Str(text) => unpack(text.chars().count()),
            other => uncaught(&format!("TypeError: cannot unpack non-iterable {} object", other.type_name())),
        };
        let target = match known(&engine_method) {
            Val::Str(name) => engine_facade_target(&ctx.root, Some(name)),
            _ => engine_facade_target(&ctx.root, None),
        };
        let Some((attr, method)) = target else {
            rows.push((tool, "_(non-facade)_".into(), "—".into(), "—".into(), 999.0));
            continue;
        };
        let Some((_, (cls_name, module))) = sub_map.iter().find(|(k, _)| *k == attr) else {
            rows.push((tool, format!("_(unknown subsystem `{attr}`)_"), "—".into(), "—".into(), 999.0));
            continue;
        };
        let file_path = format!("coordinationhub/{module}.py");
        let label = format!("`{module}.{cls_name}.{method}`");
        let Some((line_pct, branch_pct)) = coverage_for_function(&data, &file_path, &format!("{cls_name}.{method}"))
        else {
            rows.push((tool, label, "—".into(), "—".into(), 999.0));
            continue;
        };
        let br = py_float(branch_pct.trim_end_matches('%')).unwrap_or(999.0);
        rows.push((tool, label, line_pct, branch_pct, br));
    }
    rows.sort_by(|a, b| a.4.partial_cmp(&b.4).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.0.cmp(&b.0)));
    let mut out = vec![
        "| Tool | Subsystem method | Line cov | Branch cov |".to_string(),
        "|------|------------------|----------|------------|".to_string(),
    ];
    for (tool, label, line_pct, branch_pct, _) in rows {
        out.push(format!("| `{tool}` | {label} | {line_pct} | {branch_pct} |"));
    }
    out.join("\n")
}

// ------------------------------------------------------------------
// Stale-phrase scanner
// ------------------------------------------------------------------

fn starts_at(chars: &[char], at: usize, lit: &str) -> bool {
    let mut i = at;
    for ch in lit.chars() {
        if chars.get(i) != Some(&ch) {
            return false;
        }
        i += 1;
    }
    true
}

fn skip_ws(chars: &[char], mut i: usize) -> usize {
    while i < chars.len() && py_isspace(chars[i]) {
        i += 1;
    }
    i
}

fn comment_starts(chars: &[char]) -> impl Iterator<Item = usize> + '_ {
    (0..chars.len()).filter(move |&i| starts_at(chars, i, "<!--"))
}

/// `<!--\s*ALLOW-STALE\b`
fn allow_stale_token(chars: &[char]) -> bool {
    comment_starts(chars).any(|i| {
        let j = skip_ws(chars, i + 4);
        if !starts_at(chars, j, "ALLOW-STALE") {
            return false;
        }
        let k = j + "ALLOW-STALE".len();
        k >= chars.len() || !pyio::py_word(chars[k])
    })
}

/// After `<!--\s*ALLOW-STALE:\s*`, the index of the `\S` character.
fn allow_stale_reason_start(chars: &[char], i: usize) -> Option<usize> {
    let j = skip_ws(chars, i + 4);
    if !starts_at(chars, j, "ALLOW-STALE:") {
        return None;
    }
    let m = skip_ws(chars, j + "ALLOW-STALE:".len());
    (m < chars.len()).then_some(m)
}

/// `<!--\s*ALLOW-STALE:\s*\S[^>]*-->`
fn allow_stale_valid(chars: &[char]) -> bool {
    comment_starts(chars).any(|i| {
        let Some(m) = allow_stale_reason_start(chars, i) else { return false };
        let p = m + 1;
        match chars[p.min(chars.len())..].iter().position(|c| *c == '>') {
            Some(off) => {
                let q = p + off;
                q >= p + 2 && chars[q - 2] == '-' && chars[q - 1] == '-'
            }
            None => false,
        }
    })
}

/// `<!--\s*ALLOW-STALE:\s*(\S[^>]*?)\s*-->` -> group 1.
fn allow_stale_reason(chars: &[char]) -> Option<String> {
    for i in comment_starts(chars) {
        let Some(m) = allow_stale_reason_start(chars, i) else { continue };
        let mut k = m + 1;
        loop {
            let r = skip_ws(chars, k);
            if starts_at(chars, r, "-->") {
                return Some(chars[m..k].iter().collect());
            }
            if k < chars.len() && chars[k] != '>' {
                k += 1;
            } else {
                break;
            }
        }
    }
    None
}

fn find_stale_phrases(root: &Path) -> Vec<(String, usize, String, String)> {
    let mut hits = Vec::new();
    for rel in STALE_SCAN_TARGETS {
        let path = root.join(rel);
        if !path.exists() {
            continue;
        }
        let text = read_utf8(&path);
        for (index, line) in py_splitlines(&text).into_iter().enumerate() {
            let n = index + 1;
            let chars: Vec<char> = line.chars().collect();
            let has_token = allow_stale_token(&chars);
            let has_valid = allow_stale_valid(&chars);
            if has_token && !has_valid {
                hits.push((
                    rel.to_string(),
                    n,
                    "<malformed-allow-stale>".to_string(),
                    "ALLOW-STALE escape requires a reason: <!-- ALLOW-STALE: <one-line reason> -->".to_string(),
                ));
            }
            if has_valid {
                continue;
            }
            for (phrase, reason) in STALE_PHRASES {
                if line.contains(phrase) {
                    hits.push((rel.to_string(), n, phrase.to_string(), reason.to_string()));
                }
            }
        }
    }
    hits
}

fn list_allow_stale(root: &Path) -> Vec<(String, usize, String)> {
    let mut out = Vec::new();
    for rel in STALE_SCAN_TARGETS {
        let path = root.join(rel);
        if !path.exists() {
            continue;
        }
        let text = read_utf8(&path);
        for (index, line) in py_splitlines(&text).into_iter().enumerate() {
            let chars: Vec<char> = line.chars().collect();
            if let Some(reason) = allow_stale_reason(&chars) {
                out.push((rel.to_string(), index + 1, py_strip(&reason).to_string()));
            }
        }
    }
    out
}

// ------------------------------------------------------------------
// Marker-based rewriter
// ------------------------------------------------------------------

/// One `BLOCK_RE` match at `i`: `(name, body_start, body_end, end)`.
fn match_block(chars: &[char], i: usize) -> Option<(String, usize, usize, usize)> {
    let mut j = i + "<!-- GEN:".len();
    let name_start = j;
    while j < chars.len() && (pyio::py_word(chars[j]) || chars[j] == '-') {
        j += 1;
    }
    if j == name_start || !starts_at(chars, j, " -->") {
        return None;
    }
    let name: String = chars[name_start..j].iter().collect();
    let body_start = j + " -->".len();
    let mut k = body_start;
    while k < chars.len() {
        if starts_at(chars, k, "<!-- /GEN -->") {
            return Some((name, body_start, k, k + "<!-- /GEN -->".len()));
        }
        if starts_at(chars, k, "<!-- GEN") || starts_at(chars, k, "<!-- /GEN") {
            return None;
        }
        k += 1;
    }
    None
}

fn rewrite_markers(text: &str, generators: &[(&str, String)], source: &str) -> Result<String, String> {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len());
    let mut last = 0;
    let mut i = 0;
    while i < chars.len() {
        if starts_at(&chars, i, "<!-- GEN:") {
            if let Some((name, body_start, body_end, end)) = match_block(&chars, i) {
                let Some((_, content)) = generators.iter().find(|(n, _)| *n == name) else {
                    return Err(format!(
                        "KeyError: {}",
                        py_repr(&format!("{source}: unknown GEN marker {}", py_repr(&name)))
                    ));
                };
                out.extend(&chars[last..i]);
                if chars[body_start..body_end].contains(&'\n') {
                    out.push_str(&format!("<!-- GEN:{name} -->\n{content}\n<!-- /GEN -->"));
                } else {
                    out.push_str(&format!("<!-- GEN:{name} -->{content}<!-- /GEN -->"));
                }
                i = end;
                last = end;
                continue;
            }
        }
        i += 1;
    }
    out.extend(&chars[last..]);
    Ok(out)
}

// ------------------------------------------------------------------
// Driver
// ------------------------------------------------------------------

fn build_generators(ctx: &Ctx) -> Vec<(&'static str, String)> {
    let entries = scan_package(&ctx.root);
    let file_inventory = render_file_inventory(&entries);
    let directory_tree = render_directory_tree(&entries);
    let largest_files = render_largest_files(&entries);
    let mcp_tools = render_mcp_tools(&get_mcp_tools(ctx));
    let dispatch_coverage = render_dispatch_coverage(ctx);
    let test_count = get_test_count(&ctx.root);
    let schema_version = get_schema_version(&ctx.root);
    let tool_count = py_len(&import_value(ctx, "coordinationhub.schemas", "TOOL_SCHEMAS")).to_string();
    let cli_count = py_len(&import_value(ctx, "coordinationhub.cli", "_COMMANDS")).to_string();
    let version = get_version(&ctx.root);
    vec![
        ("file-inventory", file_inventory),
        ("directory-tree", directory_tree),
        ("largest-files", largest_files),
        ("mcp-tools", mcp_tools),
        ("dispatch-coverage", dispatch_coverage),
        ("test-count", test_count),
        ("test-count-baseline", "633".to_string()),
        ("audit-closed-count", "153".to_string()),
        ("schema-version", schema_version),
        ("tool-count", tool_count),
        ("cli-count", cli_count),
        ("version", version),
    ]
}

fn main() {
    let (root, argv) = pyport::take_root(std::env::args().skip(1).collect());
    let args = PARSER.parse_args(&argv);
    let ctx = Ctx { loader: Loader::new(&root), root };

    if args.flag("check_tier_coverage") {
        let nudges = check_tier_coverage(&scan_package(&ctx.root));
        if nudges.is_empty() {
            print_out("LOC_TIERS coverage is clean — every non-primitive-shaped file is explicitly listed.");
            pyio::exit(0);
        }
        for (path, tier) in nudges {
            print_err(&format!(
                "NUDGE: {path} pattern-matches tier {} but is not in LOC_TIERS. Add a TierEntry or move the file \
                 out of the matched namespace.",
                py_repr(tier)
            ));
        }
        pyio::exit(1);
    }

    if args.flag("list_allow_stale") {
        let rows = list_allow_stale(&ctx.root);
        if rows.is_empty() {
            print_out("No ALLOW-STALE escapes in current-state docs.");
            pyio::exit(0);
        }
        for (rel, n, reason) in rows {
            print_out(&format!("{rel}:{n}: {reason}"));
        }
        pyio::exit(0);
    }

    let check = args.flag("check");
    let generators = build_generators(&ctx);

    let mut any_drift = false;
    for rel in DOC_TARGETS {
        let path = ctx.root.join(rel);
        if !path.exists() {
            print_out(&format!("skip (missing): {rel}"));
            continue;
        }
        let old = read_utf8(&path);
        let new = rewrite_markers(&old, &generators, rel).unwrap_or_else(|exc| uncaught(&exc));
        if old != new {
            any_drift = true;
            if check {
                print_out(&format!("DRIFT: {rel}"));
            } else {
                pyio::write_text_utf8(&path, &new).unwrap_or_else(|exc| uncaught(&exc));
                print_out(&format!("updated: {rel}"));
            }
        } else if !check {
            print_out(&format!("clean:   {rel}"));
        }
    }

    let stale_hits = find_stale_phrases(&ctx.root);
    if !stale_hits.is_empty() {
        for (rel, n, phrase, reason) in &stale_hits {
            print_err(&format!("STALE: {rel}:{n}: {} — {reason}", py_repr(phrase)));
        }
        if check {
            print_err(
                "\nStale-phrase hits detected in current-state docs. Reword the prose, or annotate the line with \
                 '<!-- ALLOW-STALE -->' if it is a deliberate cross-reference.",
            );
            pyio::exit(1);
        }
    }

    if check && any_drift {
        print_err("\nDoc drift detected. Run 'python scripts/gen_docs.py' to regenerate.");
        pyio::exit(1);
    }
    pyio::exit(0);
}
